{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.online_offline_customer_base as ( with overall_data as ( select \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, \'shopify\' as channel, pincode, city_mapped as district, email, customer_name, order_timestamp::date as order_date, order_name, quantity, rto_quant, dto_quant, cancel_quant, gross_sales, rto_sales, dto_sales, cancel_sales, discount, size, payment_channel, sku_group, case when lower(ifnull(discount_code,\'others\')) like \'%eco%\' or lower(ifnull(discount_code,\'others\')) like \'%influ%\' or lower(ifnull(discount_code,\'others\')) like \'%rms%\' or tags = \'FLITS_LOGICERP\' or lower(ifnull(discount_code,\'others\')) like \'%creator%\' then 1 else 0 end as removing_flag from snitch_db.maplemonk.fact_items_snitch union all select \'+91\' || RIGHT(REGEXP_REPLACE(a.phone, \'[^0-9]\', \'\'), 10) AS phone_no, case when marketplace_mapped = \'SNITCH - JAYANAGAR\' then \'SNITCH - COCO - JAYANAGAR\' else marketplace_mapped end AS CHANNEL, b.PINCODE as pincode, b.CITY as district, email, name as customer_name, order_date, order_name, suborder_quantity as quantity, 0 as rto_quant, 0 as dto_quant, 0 as cancel_quant, selling_price as gross_sales, 0 as rto_sales, 0 as dto_sales, 0 as cancel_sales, discount, size, \'prepaid\' as payment_channel, sku_group, case when lower(a.sku_group) like \'cb%\' or marketplace_mapped in (\'SNITCH - WH - B2B\', \'SNITCH - SNITCH X\', \'SNITCH - WH - M P\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - U.P\', \'SNITCH - WH - NORTH\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA\' , \'SNITCH - WH - EMIZA\', \'SNITCH - WH - YELHANKA 2\') or a.doc_prefix in (\'OMS\',\'QCOM\') then 1 else 0 end as removing_flag from snitch_db.maplemonk.STORE_fact_items_offline a left join snitch_db.maplemonk.store_details_20260128 b on case when A.marketplace_mapped = \'SNITCH - JAYANAGAR\' then \'SNITCH - COCO - JAYANAGAR\' else marketplace_mapped end = b.STORE ), last_marketplace as ( select phone_no, channel, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data where removing_flag = 0 ), customer_segmentation as ( select phone_no, case when offline_buyer > 0 and shopify_buyer > 0 then \'online+offline\' when shopify_buyer > 0 then \'online_buyer\' else \'offline_buyer\' end as customer_channel from ( select phone_no, sum(case when channel = \'shopify\' then quantity end) as shopify_buyer, sum(case when channel != \'shopify\' then quantity end) as offline_buyer from overall_data where removing_flag = 0 group by 1) ), pre_category_data as ( SELECT a.phone_no, a.order_date, LISTAGG(b.category, \', \') WITHIN GROUP (ORDER BY b.category) AS all_category FROM overall_data a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group where a.removing_flag = 0 GROUP BY phone_no, order_date ), first_purchased_category as ( select phone_no, all_category, row_number() over (partition by phone_no order by order_date asc) as rn from pre_category_data ), pincode as ( select phone_no, pincode, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data where removing_flag = 0 ), district as ( select phone_no, district, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data where removing_flag = 0 ), email as ( select phone_no, email, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data where removing_flag = 0 ), first_name as ( select phone_no, INITCAP(SPLIT_PART(customer_name, \' \', 1)) AS first_name, INITCAP(SPLIT_PART(customer_name, \' \', 2)) AS last_name, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data where removing_flag = 0 ), order_data as ( select phone_no, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 30 then order_name end) as last_1_month_orders, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 90 then order_name end) as last_3_months_orders, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 180 then order_name end) as last_6_months_orders, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 360 then order_name end) as last_12_months_orders, count(distinct case when order_date >= \'2023-11-01\' then order_name end) as orders_from_nov, count(distinct order_name) as gross_orders, sum(quantity) as gross_items, sum(quantity - rto_quant - dto_quant - cancel_quant) as net_items, sum(gross_sales) as gross_revenue, sum(gross_sales - rto_sales - dto_sales - cancel_sales) as net_revenue, sum(case when datediff(day,order_date,current_date) <= 365 then (gross_sales - rto_sales - dto_sales - cancel_sales) end) as net_revenue_last12m, DIV0(sum(gross_sales) , NULLIF(count(distinct order_name),0)) as gross_aov, DIV0(sum(dto_quant) , NULLIF(sum(quantity), 0)) * 100 as return_percentage, DIV0(sum(discount) , NULLIF(sum(discount + gross_sales), 0)) * 100 as discount_percentage, DIV0(sum(cancel_quant) , NULLIF(sum(quantity), 0)) * 100 as cancel_percentage, sum(discount) as gross_discount, mode(new_size) as recommend_size, DIV0(count(distinct case when lower(payment_channel) = \'cod\' then order_name end) , NULLIF(count(distinct order_name), 0)) * 100 as cod_percentage, 100 - DIV0(count(distinct case when lower(payment_channel) = \'cod\' then order_name end) , NULLIF(count(distinct order_name), 0)) * 100 as prepaid_percentage, mode(b.category) as frequently_purchased_category, mode(a.sku_group) as frequently_purchased_sku_group, DIV0(sum(gross_sales) , NULLIF(sum(quantity), 0)) as average_selling_price, min(order_date) as first_order_date, max(order_date) as last_order_date from (select *,CASE WHEN SIZE = \'XS\' OR SIZE = \'28\' then \'XS\' WHEN SIZE = \'S\' OR SIZE = \'30\' THEN \'S\' WHEN SIZE = \'M\' OR SIZE = \'32\' THEN \'M\' WHEN SIZE = \'L\' OR SIZE = \'34\' THEN \'L\' WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN \'XL\' WHEN SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN SIZE = \'3XL\' THEN \'XL3\' WHEN SIZE = \'4XL\' THEN \'XL4\' WHEN SIZE = \'5XL\' THEN \'XL5\' WHEN SIZE = \'6XL\' THEN \'XL6\' end as new_size from overall_data ) a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group where a.removing_flag = 0 group by 1 ), pre_main_data as ( select phone_no, order_date, sum(gross_sales) from overall_data where removing_flag = 0 group by 1,2 ), order_timeline as ( select phone_no, order_date, row_number() over (partition by phone_no order by order_date asc) as rn from pre_main_data ), order_differences AS ( SELECT phone_no, MAX(CASE WHEN rn = 1 THEN order_date END) AS first_order_date, MAX(CASE WHEN rn = 2 THEN order_date END) AS second_order_date, MAX(CASE WHEN rn = 3 THEN order_date END) AS third_order_date FROM order_timeline WHERE rn <= 3 GROUP BY 1 ), days_diff as ( SELECT phone_no, coalesce(DATEDIFF(day, first_order_date, second_order_date),\'-1\') AS time_between_1_and_2_order, coalesce(DATEDIFF(day, second_order_date, third_order_date),\'-1\') AS time_between_2_and_3_order FROM order_differences WHERE second_order_date IS NOT NULL ), main_data as ( select d.phone_no, d.last_1_month_orders, d.last_3_months_orders, d.last_6_months_orders, d.last_12_months_orders, d.orders_from_nov, d.gross_orders, d.gross_items, d.net_items, d.gross_revenue, d.net_revenue, d.net_revenue_last12m, d.gross_aov, d.return_percentage, d.discount_percentage, d.cancel_percentage, d.gross_discount, coalesce(d.recommend_size,\'-1\') as recommend_size, d.cod_percentage, d.prepaid_percentage, d.frequently_purchased_category, d.frequently_purchased_sku_group, d.average_selling_price, d.first_order_date, d.last_order_date, b.pincode, c.district, e.email as email, f.first_name, f.last_name, coalesce(g.time_between_1_and_2_order,-1) as time_between_1_and_2_order, coalesce(g.time_between_2_and_3_order,-1) as time_between_2_and_3_order, cs.customer_channel, DIV0(datediff(day,first_order_date,last_order_date),gross_orders) as average_time_duration_between_purchase, fpc.all_category as first_purchased_categories, case WHEN Pincode LIKE \'11%\' THEN \'Delhi\' WHEN Pincode LIKE \'12%\' OR Pincode LIKE \'13%\' THEN \'Haryana\' WHEN Pincode LIKE \'14%\' OR Pincode LIKE \'15%\' THEN \'Punjab\' WHEN Pincode LIKE \'16%\' THEN \'Chandigarh\' WHEN Pincode LIKE \'17%\' THEN \'Himachal Pradesh\' WHEN Pincode LIKE \'18%\' OR Pincode LIKE \'19%\' THEN \'Jammu and Kashmir, Ladakh\' WHEN Pincode BETWEEN \'200000\' AND \'289999\' THEN \'Uttar Pradesh, Uttarakhand\' WHEN Pincode BETWEEN \'300000\' AND \'349999\' THEN \'Rajasthan\' WHEN Pincode BETWEEN \'360000\' AND \'399999\' AND Pincode NOT LIKE \'396%\' THEN \'Gujarat\' WHEN Pincode LIKE \'396%\' THEN \'Dadra & Nagar Haveli and Daman & Diu\' WHEN Pincode BETWEEN \'400000\' AND \'449999\' AND Pincode NOT LIKE \'403%\' THEN \'Maharashtra\' WHEN Pincode LIKE \'403%\' THEN \'Goa\' WHEN Pincode BETWEEN \'450000\' AND \'489999\' THEN \'Madhya Pradesh\' WHEN Pincode LIKE \'49%\' THEN \'Chhattisgarh\' WHEN Pincode LIKE \'50%\' THEN \'Telangana\' WHEN Pincode BETWEEN \'510000\' AND \'539999\' THEN \'Andhra Pradesh\' WHEN Pincode BETWEEN \'560000\' AND \'599999\' THEN \'Karnataka\' WHEN Pincode BETWEEN \'600000\' AND \'669999\' THEN \'Tamil Nadu\' WHEN Pincode LIKE \'605%\' THEN \'Puducherry\' WHEN Pincode BETWEEN \'670000\' AND \'699999\' AND Pincode NOT LIKE \'682%\' THEN \'Kerala\' WHEN Pincode LIKE \'682%\' THEN \'Lakshadweep\' WHEN Pincode BETWEEN \'700000\' AND \'749999\' AND Pincode NOT LIKE \'737%\' AND Pincode NOT LIKE \'744%\' THEN \'West Bengal\' WHEN Pincode LIKE \'737%\' THEN \'Sikkim\' WHEN Pincode LIKE \'744%\' THEN \'Andaman and Nicobar Islands\' WHEN Pincode BETWEEN \'750000\' AND \'779999\' THEN \'Odisha\' WHEN Pincode LIKE \'78%\' THEN \'Assam\' WHEN Pincode BETWEEN \'790000\' AND \'799999\' THEN \'Arunachal Pradesh\' WHEN Pincode BETWEEN \'793000\' AND \'794999\' THEN \'Meghalaya\' WHEN Pincode LIKE \'795%\' THEN \'Manipur\' WHEN Pincode LIKE \'796%\' THEN \'Mizoram\' WHEN Pincode BETWEEN \'797000\' AND \'798999\' THEN \'Nagaland\' WHEN Pincode LIKE \'799%\' THEN \'Tripura\' WHEN Pincode BETWEEN \'800000\' AND \'859999\' THEN \'Bihar, Jharkhand\' WHEN Pincode BETWEEN \'900000\' AND \'999999\' THEN \'Army Postal Service\' ELSE \'Unknown\' END AS state from order_data d left join pincode b on d.phone_no = b.phone_no left join district c on d.phone_no = c.phone_no left join email e on d.phone_no = e.phone_no left join first_name f on d.phone_no = f.phone_no left join days_diff g on d.phone_no = g.phone_no left join customer_segmentation cs on d.phone_no = cs.phone_no left join first_purchased_category fpc on d.phone_no = fpc.phone_no where b.rn=1 and c.rn=1 and e.rn=1 and f.rn=1 and fpc.rn = 1 ), main_data2 as ( select a.*,b.channel, row_number() over (partition by a.phone_no order by DATEDIFF(\'day\', LAST_ORDER_DATE, CURRENT_DATE) asc) as rn from main_data a left join last_marketplace b on a.phone_no = b.phone_no where b.rn = 1 ) select * from main_data2 where rn = 1 ); create or replace table snitch_db.maplemonk.rfm_new as WITH base AS ( SELECT EMAIL as \"id_email\", PHONE_NO as id_phone, FIRST_NAME as id_name, DATEDIFF(\'day\', LAST_ORDER_DATE, CURRENT_DATE) AS recency_score, GROSS_ORDERS AS frequency_score, GROSS_REVENUE AS monetary_score, PINCODE, DISTRICT, STATE, last_name, FIRST_ORDER_DATE, LAST_ORDER_DATE, LAST_1_MONTH_ORDERS, LAST_3_MONTHS_ORDERS, LAST_6_MONTHS_ORDERS, LAST_12_MONTHS_ORDERS, AVERAGE_TIME_DURATION_BETWEEN_PURCHASE, TIME_BETWEEN_1_AND_2_ORDER, TIME_BETWEEN_2_AND_3_ORDER, NET_ITEMS, GROSS_REVENUE, div0(GROSS_REVENUE,GROSS_ORDERS) as aov, RETURN_PERCENTAGE, DISCOUNT_PERCENTAGE, CANCEL_PERCENTAGE, GROSS_DISCOUNT, RECOMMEND_SIZE, COD_PERCENTAGE, PREPAID_PERCENTAGE, FREQUENTLY_PURCHASED_CATEGORY, FREQUENTLY_PURCHASED_SKU_GROUP, AVERAGE_SELLING_PRICE, customer_channel, channel, FIRST_PURCHASED_CATEGORIES FROM snitch_db.maplemonk.online_offline_customer_base ), quartiles AS ( SELECT PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY frequency_score) AS Q1f, PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY frequency_score) AS Q2f, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY frequency_score) AS Q3f, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY monetary_score) AS Q1m, PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY monetary_score) AS Q2m, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY monetary_score) AS Q3m, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY recency_score) AS Q1r, PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY recency_score) AS Q2r, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY recency_score) AS Q3r FROM base ), main_data AS ( SELECT b.*, q.Q1m, q.Q2m, q.Q3m, CASE WHEN b.recency_score <= q.Q1r THEN \'High\' WHEN b.recency_score <= q.Q2r AND b.recency_score > q.Q1r THEN \'Medium\' ELSE \'Low\' END AS recency_category, CASE WHEN b.frequency_score > 2 THEN \'High\' WHEN b.frequency_score = 2 THEN \'Medium\' WHEN b.frequency_score = 1 THEN \'Low\' ELSE \'Very_Low\' END AS frequency_category, CASE WHEN b.monetary_score >= q.Q3m THEN \'High\' WHEN b.monetary_score >= q.Q2m AND b.monetary_score < q.Q3m THEN \'Medium\' ELSE \'Low\' END AS monetary_category FROM base b, quartiles q ), categorized_data AS ( SELECT \"id_email\",id_phone,id_name,recency_score,frequency_score,monetary_score, PINCODE, DISTRICT, STATE, last_name, FIRST_ORDER_DATE, LAST_ORDER_DATE, LAST_1_MONTH_ORDERS, LAST_3_MONTHS_ORDERS, LAST_6_MONTHS_ORDERS, LAST_12_MONTHS_ORDERS, AVERAGE_TIME_DURATION_BETWEEN_PURCHASE, TIME_BETWEEN_1_AND_2_ORDER, TIME_BETWEEN_2_AND_3_ORDER, NET_ITEMS, GROSS_REVENUE, aov, RETURN_PERCENTAGE, DISCOUNT_PERCENTAGE, CANCEL_PERCENTAGE, GROSS_DISCOUNT, RECOMMEND_SIZE, COD_PERCENTAGE, PREPAID_PERCENTAGE, FREQUENTLY_PURCHASED_CATEGORY, FREQUENTLY_PURCHASED_SKU_GROUP, AVERAGE_SELLING_PRICE, customer_channel, channel, FIRST_PURCHASED_CATEGORIES, recency_category AS recency, frequency_category AS frequency, monetary_category AS monetary, CASE WHEN frequency = \'High\' AND monetary = \'High\' AND recency = \'High\' THEN \'Best\' WHEN frequency = \'Medium\' AND monetary = \'High\' AND recency = \'High\' THEN \'Big_spenders\' WHEN frequency = \'High\' AND monetary = \'High\' AND recency = \'Medium\' THEN \'Consistent_spenders\' WHEN frequency = \'Medium\' AND monetary = \'Medium\' AND recency = \'High\' THEN \'Recent_buyers_high_spenders\' WHEN frequency = \'High\' AND monetary = \'Medium\' AND recency = \'High\' THEN \'Loyal_medium_spenders\' WHEN frequency = \'Medium\' AND monetary = \'Low\' AND recency = \'High\' THEN \'Recent_buyers_low_spenders\' WHEN frequency = \'High\' AND monetary = \'Low\' AND recency = \'High\' THEN \'Loyal_low_spenders\' WHEN frequency = \'High\' AND monetary = \'Low\' AND recency = \'Medium\' THEN \'Potential_loyalists_high_spenders\' WHEN frequency = \'High\' AND monetary = \'Medium\' AND recency = \'Medium\' THEN \'Potential_loyalists_low_spenders\' WHEN frequency = \'Low\' AND monetary = \'High\' AND recency = \'High\' THEN \'Recent_big_spenders\' WHEN frequency = \'Low\' AND monetary = \'Low\' AND recency = \'High\' THEN \'New_customers_low_spenders\' WHEN frequency = \'Low\' AND monetary = \'Medium\' AND recency = \'High\' THEN \'New_customers_medium_spenders\' WHEN frequency = \'High\' AND monetary = \'High\' AND recency = \'Low\' THEN \'Dormant_VIPs\' WHEN frequency = \'Medium\' AND monetary = \'High\' AND recency = \'Low\' THEN \'High_potential_lapsed\' WHEN frequency = \'High\' AND monetary = \'Low\' AND recency = \'Low\' THEN \'Dormant_loyalists_low_spenders\' WHEN frequency = \'High\' AND monetary = \'Medium\' AND recency = \'Low\' THEN \'Dormant_loyalists_medium_spenders\' WHEN frequency = \'Low\' AND monetary = \'High\' AND recency = \'Medium\' THEN \'High_value_infrequent_buyers\' WHEN frequency = \'Medium\' AND monetary = \'High\' AND recency = \'Medium\' THEN \'Occassional_big_spenders\' WHEN frequency = \'Medium\' AND monetary = \'Low\' AND recency = \'Medium\' THEN \'Active_customers_low_spenders\' WHEN frequency = \'Low\' AND monetary = \'Medium\' AND recency = \'Medium\' THEN \'Lapsed_customers\' WHEN frequency = \'Medium\' AND monetary = \'Medium\' AND recency = \'Medium\' THEN \'Active_customers_medium_spenders\' WHEN frequency = \'Low\' AND monetary = \'High\' AND recency = \'Low\' THEN \'High_value_lost_customers\' WHEN frequency = \'Low\' AND monetary = \'Low\' AND recency = \'Low\' THEN \'Lost_causes\' WHEN frequency = \'Medium\' AND monetary = \'Low\' AND recency = \'Low\' THEN \'Inactive_customers\' WHEN frequency = \'Very_Low\' AND monetary = \'Low\' AND recency = \'Low\' THEN \'Inactive_customers\' WHEN frequency = \'Low\' AND monetary = \'Medium\' AND recency = \'Low\' THEN \'Inactive_customers\' WHEN frequency = \'Medium\' AND monetary = \'Medium\' AND recency = \'Low\' THEN \'Inactive_customers\' WHEN frequency = \'Low\' AND monetary = \'Low\' AND recency = \'Medium\' THEN \'Inactive_customers\' END AS customer_category FROM main_data ), main_data2 as ( select \'nov2024\' as timeline, \"id_email\" as \"id_email\", id_phone as \"identity\", id_name, customer_category as \"CUSTOMER_CATEGORY2\", recency_score as \"Last_purchased_days\", frequency_score as \"GROSS_ORDERS\", monetary_score as \"Total_revenue\", PINCODE as \"Pincode\", DISTRICT as \"District\", STATE as \"State_Name\", last_name as \"Last Name\", DATEDIFF(\'day\', FIRST_ORDER_DATE, CURRENT_DATE) AS \"DAYS_SINCE_FIRST_ORDER\", LAST_1_MONTH_ORDERS as \"LAST_1_MONTH_ORDERS\", LAST_3_MONTHS_ORDERS as \"LAST_3_MONTHS_ORDERS\", LAST_6_MONTHS_ORDERS as \"LAST_6_MONTHS_ORDERS\", LAST_12_MONTHS_ORDERS as \"LAST_12_MONTHS_ORDERS\", AVERAGE_TIME_DURATION_BETWEEN_PURCHASE as \"AVERAGE_TIME_DURATION_BETWEEN_PURCHASE\", TIME_BETWEEN_1_AND_2_ORDER as \"TIME_BETWEEN_1_AND_2_ORDER\", TIME_BETWEEN_2_AND_3_ORDER as \"TIME_BETWEEN_2_AND_3_ORDER\", NET_ITEMS as \"Net_units\", GROSS_REVENUE as \"GROSS_REVENUE\", aov as \"GROSS_AOV\", RETURN_PERCENTAGE as \"Return_percentage\", DISCOUNT_PERCENTAGE as \"Discount%\", CANCEL_PERCENTAGE as \"Cancel_percentage\", GROSS_DISCOUNT as \"Total_discount\", RECOMMEND_SIZE as \"RECOMMEND_SIZE\", COD_PERCENTAGE AS \"COD_PERCENTAGE\", PREPAID_PERCENTAGE AS \"PREPAID_PERCENTAGE\", FREQUENTLY_PURCHASED_CATEGORY AS \"FREQUENTLY_PURCHASED_CATEGORY\", FREQUENTLY_PURCHASED_SKU_GROUP AS \"FREQUENTLY_PURCHASED_SKU_GROUP\", AVERAGE_SELLING_PRICE AS \"AVERAGE_SELLING_PRICE\", customer_channel AS \"CUSTOMER_CHANNEL\", channel AS \"CHANNEL\", FIRST_PURCHASED_CATEGORIES AS \"FIRST_PURCHASED_CATEGORIES\" from categorized_data where trim(lower(\"id_email\")) like \'%@%\' and length(id_phone) = 13 and id_name IS NOT NULL AND \"identity\" IS NOT NULL AND id_phone IS NOT NULL AND customer_category IS NOT NULL AND recency_score IS NOT NULL AND frequency_score IS NOT NULL AND monetary_score IS NOT NULL AND pincode IS NOT NULL AND district IS NOT NULL AND state IS NOT NULL AND last_name IS NOT NULL ), main_data3 as ( select timeline, \"identity\", \"id_email\", id_name as \"id_name\", \"CUSTOMER_CATEGORY2\", \"Last_purchased_days\", \"GROSS_ORDERS\", \"Total_revenue\", \"Pincode\", \"District\", \"State_Name\", \"Last Name\", \"DAYS_SINCE_FIRST_ORDER\", \"LAST_1_MONTH_ORDERS\", \"LAST_3_MONTHS_ORDERS\", \"LAST_6_MONTHS_ORDERS\", \"LAST_12_MONTHS_ORDERS\", \"AVERAGE_TIME_DURATION_BETWEEN_PURCHASE\", \"TIME_BETWEEN_1_AND_2_ORDER\", \"TIME_BETWEEN_2_AND_3_ORDER\", \"Net_units\", \"GROSS_REVENUE\", \"GROSS_AOV\", \"Return_percentage\", \"Discount%\", \"Cancel_percentage\", \"Total_discount\", \"RECOMMEND_SIZE\", \"COD_PERCENTAGE\", \"PREPAID_PERCENTAGE\", \"FREQUENTLY_PURCHASED_CATEGORY\", \"FREQUENTLY_PURCHASED_SKU_GROUP\", \"AVERAGE_SELLING_PRICE\", \"CUSTOMER_CHANNEL\", \"CHANNEL\", \"FIRST_PURCHASED_CATEGORIES\", row_number() over (partition by \"identity\" order by \"Last_purchased_days\" asc) as rn from main_data2 ) select \"identity\", \"id_email\", \"id_name\", \"CUSTOMER_CATEGORY2\", \"Last_purchased_days\", \"GROSS_ORDERS\", \"Total_revenue\", \"Pincode\", \"District\", \"State_Name\", \"Last Name\", \"DAYS_SINCE_FIRST_ORDER\", \"LAST_1_MONTH_ORDERS\", \"LAST_3_MONTHS_ORDERS\", \"LAST_6_MONTHS_ORDERS\", \"LAST_12_MONTHS_ORDERS\", \"AVERAGE_TIME_DURATION_BETWEEN_PURCHASE\", \"TIME_BETWEEN_1_AND_2_ORDER\", \"TIME_BETWEEN_2_AND_3_ORDER\", \"Net_units\", \"GROSS_REVENUE\", \"GROSS_AOV\", \"Return_percentage\", \"Discount%\", \"Cancel_percentage\", \"Total_discount\", \"RECOMMEND_SIZE\", \"COD_PERCENTAGE\", \"PREPAID_PERCENTAGE\", \"FREQUENTLY_PURCHASED_CATEGORY\", \"FREQUENTLY_PURCHASED_SKU_GROUP\", \"AVERAGE_SELLING_PRICE\", \"CUSTOMER_CHANNEL\", \"CHANNEL\", \"FIRST_PURCHASED_CATEGORIES\" from main_data3 where rn = 1 and SUBSTR(\"identity\", 4, 1) IN (\'9\', \'8\', \'7\', \'6\'); ;",
                    "transaction": true
